DECLARE @NextID bigint;

SELECT @NextID = LastID FROM Working.Load_iLocate_NextID;

SELECT @NextID AS NextID

DECLARE @NextID bigint = ?;
DECLARE @EndID bigint = 0;

SET @EndID  = @NextID  + 4000000;

Update LNK
SET LNK.iLocate = S.iLocate
FROM dv.LNK_Scan LNK
JOIN [working].[Load_iLocate_Stg] S ON S.ID = LNK.[TrackAndTraceID];

UPDATE FastwayDW.[working].[Load_iLocate_NextID]
SET LastID = @EndID;
